#include <iostream>
#include <print>
#include <string>

class Converter {
public:
    virtual double convert(double x) const {
        return x;
    }

    virtual std::string name() const {
        return "без преобразования";
    }

    virtual ~Converter() = default;
};

class CToF : public Converter {
public:
    double convert(double x) const override {
        return x * 9 / 5 + 32;
    }

    std::string name() const override {
        return "°C -> °F";
    }
};

class FToC : public Converter {
public:
    double convert(double x) const override {
        return (x - 32) * 5 / 9;
    }

    std::string name() const override {
        return "°F -> °C";
    }
};

class KmToMiles : public Converter {
public:
    double convert(double x) const override {
        return x * 0.621371;
    }

    std::string name() const override {
        return "км -> мили";
    }
};

class MilesToKm : public Converter {
public:
    double convert(double x) const override {
        return x / 0.621371;
    }

    std::string name() const override {
        return "мили -> км";
    }
};

void show(const Converter &c, double x) {
    std::println("{}: {:.2f} = {:.2f}", c.name(), x, c.convert(x));
}

int main() {
    CToF c2f;
    FToC f2c;
    KmToMiles km2mi;
    MilesToKm mi2km;
    std::string code;
    double x;
    while (std::cin >> code >> x) {
        if (code == "c2f") {
            show(c2f, x);
        } else if (code == "f2c") {
            show(f2c, x);
        } else if (code == "km2mi") {
            show(km2mi, x);
        } else {
            show(mi2km, x);
        }
    }
    return 0;
}

