#include <iostream>
#include <print>
#include <string>

class Printer {
public:
    virtual void print(long long x) const {
        std::println("число {}", x);
    }

    virtual void print(const std::string &s) const {
        std::println("строка {}", s);
    }

    virtual ~Printer() = default;
};

class Boxed : public Printer {
public:
    using Printer::print;

    void print(const std::string &s) const override {
        std::println("[{}]", s);
    }
};

int main() {
    Boxed boxed;
    std::string kind;
    while (std::cin >> kind) {
        if (kind == "int") {
            long long x;
            std::cin >> x;
            boxed.print(x);
        } else {
            std::string s;
            std::cin >> s;
            boxed.print(s);
        }
    }
    return 0;
}

